import React from "react";
import mock01 from '../assets/images/VR.jpg';
import mock02 from '../assets/images/mock02.png';
import mock03 from '../assets/images/mock03.png';
import mock04 from '../assets/images/mock04.png';
import mock05 from '../assets/images/mock05.png';
import mock06 from '../assets/images/mock06.png';
import mock07 from '../assets/images/mock07.png';
import mock08 from '../assets/images/mock08.png';
import mock09 from '../assets/images/mock09.png';
import mock10 from '../assets/images/mock10.png';
import '../assets/styles/Project.scss';

function Project() {
    return(
    <div className="projects-container" id="projects">
        <h1>Personal Projects</h1>
        <div className="projects-grid">
            <div className="project">
                <a href="https://doi.org/10.2352/EI.2022.34.8.IMAGE-255" target="_blank" rel="noreferrer"><img src={mock01} className="zoom" alt="thumbnail" width="100%"/></a>
                {/* <a href="https://doi.org/10.2352/EI.2022.34.8.IMAGE-255" target="_blank" rel="noreferrer"><h2>VR Facial Expression Tracking</h2></a> */}
                <p> <b><big>Classifier Guided Domain Adaptation for VR Facial Expression Tracking</big></b>
                     <br></br>
                   <small>Authors: <b>Xiaoyu Ji</b>, Justin Yang, Jishang Wei, Yvonne Huang, Shibo Zhang, Qian Lin, Jan P Allebach, and Fengqing Zhu
                    </small>
                    <br></br><br></br>Reenacted facial expressions of participants wearing VR headset to virtual characters.
                   Developed a VR facial expression tracking domain adaptation model with designed backpropagation steps and subjective study evaluation. 

                </p>
            </div>
            <div className="project">
                <a href="https://doi.org/10.2352/EI.2022.34.8.IMAGE-255" target="_blank" rel="noreferrer"><img src={mock02} className="zoom" alt="thumbnail" width="100%"/></a>
                <p>
                    Developed a VR facial expression tracking domain adaptation model with designed backpropagation steps and subjective study evaluation. 
                    Authors: 
                </p>
            </div>

        </div>
    </div>
    );
}

export default Project;
